mapper.insert:
INSERT INTO T_TR_HIST_DETAIL ( TR_SNO ,TR_SEQ ,CONT_NO ,MEMBER_NO ,PT_NO ,MEMBER_PT_NO ,TR_DT ,TR_GB_CD ,TR_METHOD_GB_CD ,TR_PT ,BEF_BAL_PT ,AFR_BAL_PT ,CONT_BEF_BAL_PT ,CONT_AFR_BAL_PT ,ORGL_TR_SNO ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT ) SELECT TR_SNO ,TR_SEQ ,CONT_NO ,MEMBER_NO ,PT_NO ,MEMBER_PT_NO ,TR_DT ,TR_GB_CD ,TR_METHOD_GB_CD ,TR_PT ,BEF_BAL_PT ,AFR_BAL_PT ,CONT_BEF_BAL_PT ,CONT_AFR_BAL_PT ,ORGL_TR_SNO ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT FROM (SELECT @num:=0) AS n, (
SELECT #{trSno} AS TR_SNO , @num:=@num+1 AS TR_SEQ , #{ut.contNo} AS CONT_NO , #{memberNo} AS MEMBER_NO , #{ut.ptNo} AS PT_NO , #{ut.memberPtNo} AS MEMBER_PT_NO , CURRENT_TIMESTAMP(6) AS TR_DT , 'SC01' AS TR_GB_CD , 'ONLINE' AS TR_METHOD_GB_CD , #{ut.isuCancelReqPt} AS TR_PT , #{ut.balPt} AS BEF_BAL_PT , #{ut.balPt} - #{ut.isuCancelReqPt} AS AFR_BAL_PT , #{ut.contBalPt} AS CONT_BEF_BAL_PT , #{ut.contBalPt} - #{ut.isuCancelReqPt} AS CONT_AFR_BAL_PT , #{ut.orglTrSno} AS ORGL_TR_SNO ,#{regUserId, jdbcType=VARCHAR} AS REG_USER_ID , CURRENT_TIMESTAMP(6) AS REG_DT ,#{lastModUserId, jdbcType=VARCHAR} AS LAST_MOD_USER_ID ,CURRENT_TIMESTAMP(6) AS LAST_MOD_DT
) AS a

INSERT INTO T_TR_HIST_DETAIL ( TR_SNO ,TR_SEQ ,CONT_NO ,MEMBER_NO ,PT_NO ,MEMBER_PT_NO ,TR_DT ,TR_GB_CD ,TR_METHOD_GB_CD ,TR_PT ,BEF_BAL_PT ,AFR_BAL_PT ,CONT_BEF_BAL_PT ,CONT_AFR_BAL_PT ,ORGL_TR_SNO ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT ) SELECT TR_SNO ,TR_SEQ ,CONT_NO ,MEMBER_NO ,PT_NO ,MEMBER_PT_NO ,TR_DT ,TR_GB_CD ,TR_METHOD_GB_CD ,TR_PT ,BEF_BAL_PT ,AFR_BAL_PT ,CONT_BEF_BAL_PT ,CONT_AFR_BAL_PT ,ORGL_TR_SNO ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT FROM (
SELECT #{trSno} AS TR_SNO , #{ut.trSeq} AS TR_SEQ , #{ut.contNo} AS CONT_NO , #{memberNo} AS MEMBER_NO , #{ut.ptNo} AS PT_NO , #{ut.memberPtNo} AS MEMBER_PT_NO , CURRENT_TIMESTAMP(6) AS TR_DT , 'U001' AS TR_GB_CD , 'ONLINE' AS TR_METHOD_GB_CD , #{ut.useReqPt} AS TR_PT , #{ut.balPt} AS BEF_BAL_PT , #{ut.balPt} - #{ut.useReqPt} AS AFR_BAL_PT , #{ut.contBalPt} AS CONT_BEF_BAL_PT , #{ut.contBalPt} - #{ut.useReqPt} AS CONT_AFR_BAL_PT , null AS ORGL_TR_SNO ,#{regUserId, jdbcType=VARCHAR} AS REG_USER_ID , CURRENT_TIMESTAMP(6) AS REG_DT ,#{lastModUserId, jdbcType=VARCHAR} AS LAST_MOD_USER_ID ,CURRENT_TIMESTAMP(6) AS LAST_MOD_DT
) AS a

INSERT INTO T_TR_HIST_DETAIL ( TR_SNO ,TR_SEQ ,CONT_NO ,MEMBER_NO ,PT_NO ,MEMBER_PT_NO ,TR_DT ,TR_GB_CD ,TR_METHOD_GB_CD ,TR_PT ,BEF_BAL_PT ,AFR_BAL_PT ,CONT_BEF_BAL_PT ,CONT_AFR_BAL_PT ,ORGL_TR_SNO ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT ) SELECT TR_SNO ,TR_SEQ ,CONT_NO ,MEMBER_NO ,PT_NO ,MEMBER_PT_NO ,TR_DT ,TR_GB_CD ,TR_METHOD_GB_CD ,TR_PT ,BEF_BAL_PT ,AFR_BAL_PT ,CONT_BEF_BAL_PT ,CONT_AFR_BAL_PT ,ORGL_TR_SNO ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT FROM (SELECT @num:=0) AS n, (
SELECT #{trSno} AS TR_SNO , #{ut.trSeq} AS TR_SEQ , #{ut.contNo} AS CONT_NO , #{memberNo} AS MEMBER_NO , #{ut.ptNo} AS PT_NO , #{ut.memberPtNo} AS MEMBER_PT_NO , CURRENT_TIMESTAMP(6) AS TR_DT , 'UC01' AS TR_GB_CD , 'ONLINE' AS TR_METHOD_GB_CD , #{ut.useCancelReqPt} AS TR_PT , #{ut.balPt} AS BEF_BAL_PT , #{ut.balPt} + #{ut.useCancelReqPt} AS AFR_BAL_PT , #{ut.contBalPt} AS CONT_BEF_BAL_PT , #{ut.contBalPt} + #{ut.useCancelReqPt} AS CONT_AFR_BAL_PT , #{ut.orglTrSno} AS ORGL_TR_SNO ,#{regUserId, jdbcType=VARCHAR} AS REG_USER_ID , CURRENT_TIMESTAMP(6) AS REG_DT ,#{lastModUserId, jdbcType=VARCHAR} AS LAST_MOD_USER_ID ,CURRENT_TIMESTAMP(6) AS LAST_MOD_DT
) AS a

mapper.select:
SELECT thd.TR_SNO ,thd.TR_SEQ ,thd.CONT_NO ,thd.MEMBER_NO ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,thd.PT_NO ,thd.MEMBER_PT_NO ,thd.TR_DT ,thd.TR_GB_CD ,thd.TR_METHOD_GB_CD ,thd.TR_PT ,thd.BEF_BAL_PT ,thd.AFR_BAL_PT ,thd.CONT_BEF_BAL_PT ,thd.CONT_AFR_BAL_PT ,thd.ORGL_TR_SNO ,thd.REG_USER_ID ,thd.REG_DT ,thd.LAST_MOD_USER_ID ,thd.LAST_MOD_DT FROM T_TR_HIST_DETAIL thd INNER JOIN T_MEMBER_MST mm ON mm.MEMBER_NO = thd.MEMBER_NO INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CONVERT (ei.TARGET_VAL, INT) INNER JOIN T_TR_HIST th ON th.TR_SNO = thd.TR_SNO WHERE 1 = 1
AND thd.TR_SNO = #{trSno}
AND thd.PT_NO = #{ptNo}
AND thd.MEMBER_PT_NO = #{memberPtNo}
AND thd.ORGL_TR_SNO = #{orglTrSno}
AND thd.MEMBER_NO = #{memberNo}
AND thd.CONT_NO = #{contNo}

SELECT thd.TR_SNO ,thd.TR_SEQ ,thd.CONT_NO ,thd.MEMBER_NO ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,thd.PT_NO ,thd.MEMBER_PT_NO ,thd.TR_DT ,thd.TR_GB_CD ,thd.TR_METHOD_GB_CD ,thd.TR_PT ,thd.BEF_BAL_PT ,thd.AFR_BAL_PT ,thd.CONT_BEF_BAL_PT ,thd.CONT_AFR_BAL_PT ,thd.ORGL_TR_SNO ,thd.REG_USER_ID ,thd.REG_DT ,thd.LAST_MOD_USER_ID ,thd.LAST_MOD_DT FROM T_TR_HIST_DETAIL thd INNER JOIN T_MEMBER_MST mm ON mm.MEMBER_NO = thd.MEMBER_NO INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CONVERT (ei.TARGET_VAL, INT) WHERE 1 = 1
AND thd.TR_SNO = #{trSno}
AND thd.ORGL_TR_SNO = #{orglTrSno}
AND thd.MEMBER_NO = #{memberNo}
AND thd.CONT_NO = #{contNo}
AND thd.PT_NO = #{ptNo}
AND thd.MEMBER_PT_NO = #{memberPtNo}
AND thd.TR_GB_CD = #{trGbCd}
AND thd.TR_DT BETWEEN #{startDt} AND #{endDt}
ORDER BY thd.TR_DT DESC, thd.TR_SNO DESC, thd.TR_SEQ DESC LIMIT 1

SELECT
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'S001' THEN thd.TR_PT ELSE 0 END), 0) AS ISU_SUM,
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'SC01' THEN thd.TR_PT ELSE 0 END), 0) AS ISU_CANCEL_SUM,
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'S001' THEN 1 ELSE 0 END), 0) AS ISU_CNT,
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'SC01' THEN 1 ELSE 0 END), 0) AS ISU_CANCEL_CNT
FROM T_TR_HIST_DETAIL thd
WHERE thd.MEMBER_NO = #{memberNo}

        AND thd.CONT_NO = #{contNo}


        AND (thd.TR_SNO = #{trSno} OR thd.ORGL_TR_SNO = #{trSno})


        AND thd.TR_DT BETWEEN #{startDt} AND #{endDt}

SELECT
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'U001' THEN thd.TR_PT ELSE 0 END), 0) AS USE_SUM,
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'UC01' THEN thd.TR_PT ELSE 0 END), 0) AS USE_CANCEL_SUM,
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'U001' THEN 1 ELSE 0 END), 0) AS USE_CNT,
    COALESCE(SUM(CASE WHEN thd.TR_GB_CD = 'UC01' THEN 1 ELSE 0 END), 0) AS USE_CANCEL_CNT
FROM T_TR_HIST_DETAIL thd
WHERE thd.MEMBER_NO = #{memberNo}

        AND thd.CONT_NO = #{contNo}


        AND (thd.TR_SNO = #{trSno} OR thd.ORGL_TR_SNO = #{trSno})


        AND thd.TR_DT BETWEEN #{startDt} AND #{endDt}

SELECT
COALESCE(COUNT(thd.TR_SNO), 0)
FROM T_TR_HIST_DETAIL thd
    INNER JOIN T_TR_HIST th ON th.TR_SNO = thd.TR_SNO
WHERE 1 = 1

    AND thd.TR_SNO = #{trSno}


    AND thd.MEMBER_NO = #{memberNo}


    AND thd.CONT_NO = #{contNo}


    AND thd.PT_NO = #{ptNo}


    AND thd.MEMBER_PT_NO = #{memberPtNo}


    AND thd.TR_GB_CD = #{trGbCd}


    AND thd.TR_DT BETWEEN #{startDt} AND #{endDt}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT
ROW_NUMBER() OVER(ORDER BY thd.TR_SNO ASC, thd.TR_SEQ ASC) ROW_NUM
ROW_NUMBER() OVER(ORDER BY thd.TR_SNO DESC, thd.TR_SEQ DESC) ROW_NUM
,thd.TR_SNO ,thd.TR_SEQ ,thd.CONT_NO ,cm.CONT_NM ,thd.MEMBER_NO ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,thd.PT_NO ,thd.MEMBER_PT_NO ,thd.TR_DT ,thd.TR_GB_CD ,thd.TR_METHOD_GB_CD ,thd.TR_PT ,thd.BEF_BAL_PT ,thd.AFR_BAL_PT ,thd.CONT_BEF_BAL_PT ,thd.CONT_AFR_BAL_PT ,thd.ORGL_TR_SNO ,thd.REG_USER_ID ,thd.REG_DT ,thd.LAST_MOD_USER_ID ,thd.LAST_MOD_DT FROM T_TR_HIST_DETAIL thd INNER JOIN T_MEMBER_MST mm ON mm.MEMBER_NO = thd.MEMBER_NO INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CONVERT (ei.TARGET_VAL, INT) INNER JOIN T_TR_HIST th ON th.TR_SNO = thd.TR_SNO INNER JOIN T_CONT_MST cm ON cm.CONT_NO = thd.CONT_NO WHERE 1 = 1
AND thd.TR_SNO = #{trSno}
AND thd.MEMBER_NO = #{memberNo}
AND thd.CONT_NO = #{contNo}
AND thd.PT_NO = #{ptNo}
AND thd.MEMBER_PT_NO = #{memberPtNo}
AND thd.TR_GB_CD = #{trGbCd}
AND thd.TR_DT BETWEEN #{startDt} AND #{endDt}
ORDER BY thd.TR_SNO ASC, thd.TR_SEQ ASC
ORDER BY thd.TR_DT DESC, thd.TR_SNO DESC, thd.TR_SEQ DESC
) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
